INSERT INTO `products` (`id`, `title`, `slug`, `category_id`, `unit_id`, `product_type`, `short_description`, `description`, `image`, `price`, `sale_price`, `stock`, `min_stock`, `is_featured`, `is_discounted`, `is_tranding`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(2, 'PVC Condit Zero Calcium', 'pvc-condit-zero-calcium', 12, 3, 3, 'A PVC (Polyvinyl Chloride) pipeline is a system of pipes and fittings made from rigid plastic material, used to convey liquids or gases from one point to another.', NULL, 'products/tASHxmmfussIKnqtlQRs743KfvcxYFbkGvT8gQqY.png', '0.00', NULL, 0, 0, 0, 0, 0, 1, '2026-01-28 03:11:56', '2026-02-06 02:40:26', NULL),
(7, 'GI Flush Box', 'gi-flush-box', 27, 5, 3, 'A GI (Galvanized Iron) Flush Box is a metal electrical back box used in building wiring to house switches, sockets, regulators, and other electrical accessories inside a wall (flush mounted).', 'A GI (Galvanized Iron) Flush Box is a metal electrical back box used in building wiring to house switches, sockets, regulators, and other electrical accessories inside a wall (flush mounted).', 'products/mI15ZP90Cvz97M8Bp4ixngTmNtMAQ4U67fpeki8n.jpg', '0.00', NULL, 0, 0, 0, 0, 0, 1, '2026-01-29 07:48:42', '2026-02-07 01:31:12', NULL),
(8, 'MCB distribution box Super Line', 'mcb-distribution-box-super-line', 15, 3, 3, 'An MCB Distribution Box is an electrical enclosure used to safely distribute power', 'An MCB Distribution Box is an electrical enclosure used to safely distribute power to multiple circuits in a building. It houses Miniature Circuit Breakers (MCBs) that protect wiring and appliances from overloads and short circuits, ensuring safe and organized electrical control for homes, offices, and commercial spaces.', 'products/J1sYfKC2OpyCRopWiK52VTZfnG7RDV1Fzj8APmjN.jpg', '0.00', NULL, 0, 0, 0, 0, 0, 1, '2026-01-29 07:49:29', '2026-07-03 03:04:42', NULL),
(9, 'Junction Box', 'junction-box', 27, 3, 3, 'A junction box is a protective enclosure where electrical wires are joined,', 'A junction box is a protective enclosure used in electrical systems to safely house wire connections. It serves as a central point where electrical wires can be joined, spliced, or branched without exposing live wires. Junction boxes protect the connections from dust, moisture, mechanical damage, and accidental contact, ensuring both safety and reliability of the electrical system. They are commonly made of metal or plastic and are used in residential, commercial, and industrial wiring. In addition to safety, junction boxes help organize wiring, making maintenance, inspections, and future modifications easier. Some junction boxes also accommodate switches, outlets, or other electrical devices, providing flexibility in electrical installations', 'products/s73QYOf4tgL76CsOal6Rm0gijryiJbXMM8UmwaI7.jpg', '0.00', NULL, 0, 0, 0, 0, 0, 1, '2026-01-29 08:12:23', '2026-02-05 02:18:18', NULL),
(10, 'Consealed Box', 'consealed-box', 27, 3, 3, 'A concealed electrical box (also spelled consealed box) is a metal or PVC enclosure used in concealed or flush wiring systems to house switches,', 'A concealed electrical box (also spelled consealed box) is a metal or PVC enclosure used in concealed or flush wiring systems to house switches, sockets, or connections inside a wall or ceiling, keeping the electrical wiring hidden from view for a cleaner interior look. These are embedded in plaster or wall cavities before finishing the wall surface.', 'products/KdvH139wJToCEaTTUqicMKYhTeRPgKOZgA0O0263.jpg', '0.00', NULL, 0, 0, 0, 0, 0, 1, '2026-01-29 08:18:14', '2026-02-07 01:32:43', NULL),
(11, 'Fan Box', 'fan-box', 27, 3, 3, 'A fan box is a strong electrical box that safely supports the wiring and weight of a ceiling fan.', 'A fan box is a type of electrical enclosure specifically designed to support ceiling fans or heavy light fixtures. Unlike standard junction boxes, fan boxes are reinforced and sturdier to safely carry the weight and rotational movement of a ceiling fan without risk of loosening or falling. They are usually made of metal or high-strength plastic and are securely attached to ceiling joists or structural supports to ensure stability.\r\n\r\nIn addition to supporting the fan, the fan box houses the electrical wiring connections, protecting them from damage, dust, and accidental contact. Some fan boxes also provide mounting brackets or hardware to make installation easier. Fan boxes are widely used in residential, commercial, and industrial buildings, where safety, stability, and compliance with electrical codes are critical. They play a key role in ensuring that ceiling fans operate safely and reliably over time', 'products/AJvWT677a7ct1qYmpTdRr5jql3G0FusvlauS0HvK.jpg', '0.00', NULL, 0, 0, 0, 0, 0, 1, '2026-01-29 08:38:36', '2026-01-29 08:38:36', NULL),
(12, 'These Product are created for Testing with new one', 'these-product-are-created-for-testing-with-new-one', 18, 3, 1, 'A fan box is a type of electrical junction box designed to house wiring and support for a ceiling fan or other ceiling fixture', 'A fan box is a type of electrical junction box designed to house wiring and support for a ceiling fan or other ceiling fixture', 'products/V6sjC43JxwWljlcTeFD3Iyl4E6Sy0dONucEZrVWX.jpg', '100.00', '50.00', 0, 0, 0, 0, 0, 1, '2026-01-30 00:59:23', '2026-02-16 04:53:55', '2026-02-16 04:53:55'),
(16, 'PVC Bend', 'pvc-bend', 12, 3, 3, 'A PVC bend is a durable pipe fitting made from polyvinyl chloride, used to smoothly change flow direction in plumbing, irrigation, and piping systems.', NULL, 'products/Zo5tU0myiCzfIOTyc3bU11A6wq7H3sz122fLQVBJ.png', '0.00', NULL, 0, 0, 0, 0, 0, 1, '2026-02-02 01:30:09', '2026-02-02 01:30:09', NULL),
(17, 'PVC Junction Box', 'pvc-junction-box', 12, 3, 3, 'A PVC junction box is a protective enclosure made from plastic, used to house electrical connections safely in residential and industrial systems use.', NULL, 'products/CTMINn3SinVwm9jG7mS43pHarL6q1Ok6vNynE2dE.png', '0.00', NULL, 0, 0, 0, 0, 0, 1, '2026-02-02 04:48:01', '2026-02-06 04:31:42', NULL),
(18, 'PVC Socket Jointes', 'pvc-socket-jointes', 12, 3, 3, 'A PVC socket joint is a strong plastic fitting used to connect two PVC pipes securely, ensuring leakproof joints in plumbing and irrigation systems', NULL, 'products/lmQ7YcjmHu1KojtBj7UJUDr64BNqkR93W7tQs0hF.png', '0.00', NULL, 0, 0, 0, 0, 0, 1, '2026-02-02 05:48:07', '2026-02-06 04:32:57', NULL),
(19, 'COPPER WIRE', 'copper-wire', 33, 6, 3, 'Copper wire is a highly conductive metal wire made from pure copper, widely used in electrical and electronic applications. It offers excellent electr', NULL, 'products/k7WiY7xHoBE93KCwecDPATDG8kgF7ZZPxXgFVKks.jpg', '0.00', NULL, 0, 0, 0, 0, 0, 1, '2026-02-02 06:06:56', '2026-02-12 07:45:34', '2026-02-12 07:45:34'),
(20, 'Instant Water Heater (ABS)', 'instant-water-heater-abs', 16, 3, 3, 'Instant Water Heater (ABS) provides instant hot water with durable ABS body, fast heating, energy efficiency, and safe reliable performance for daily', NULL, 'products/d1NGybO7I07pE53Acgx8MI0LeZGaNCsTD3rgZEkM.jpg', '0.00', NULL, 0, 0, 0, 0, 0, 1, '2026-02-04 01:21:24', '2026-02-04 03:25:07', NULL),
(21, 'Storage Water Heater (CRC)', 'storage-water-heater-crc', 16, 3, 3, 'Storage Water Heater (CRC) offers reliable hot water storage with strong CRC body, fast heating, corrosion resistance, and long-lasting performance.', NULL, 'products/jVB3AnrChNUevJ55OK72mpPgCUvC9NDK6AMLnr59.png', '0.00', NULL, 0, 0, 0, 0, 0, 1, '2026-02-04 02:52:55', '2026-02-04 08:26:18', NULL),
(22, 'Storage Water Heater Glass Line', 'storage-water-heater-glass-line', 16, 3, 3, 'Storage Water Heater Glass Line provides safe hot water with glass-lined tank, fast heating, corrosion resistance, and long-lasting daily performance.', NULL, 'products/sbqYetcUnmllP3lAHJDyp0hmlx3pAPVr3CAG78nf.png', '0.00', NULL, 0, 0, 0, 0, 0, 1, '2026-02-04 03:19:17', '2026-02-04 06:05:24', NULL),
(23, 'Exhaust Fan', 'exhaust-fan', 14, 3, 3, 'Exhaust Fan ensures fresh air circulation by removing heat, smoke, and odors. Durable, efficient, and ideal for kitchens, bathrooms, and offices.', NULL, 'products/vHkMNxCb7Ov3mVLPL85hWk1C320Kl1Poyf7TSyuW.png', '0.00', NULL, 0, 0, 0, 0, 0, 1, '2026-02-04 05:32:08', '2026-02-04 05:32:08', NULL),
(29, 'Wall Fan', 'wall-fan', 14, 3, 3, 'Wall Fan provides powerful air circulation with space-saving wall mounting. Durable, energy-efficient, and ideal for homes, shops, and offices', NULL, 'products/qkG8FBdvdRVT02NZL3skRZ7Ic1XqZxVUAymgFtn6.png', '0.00', NULL, 0, 0, 0, 0, 0, 1, '2026-02-04 06:10:53', '2026-02-04 06:10:53', NULL),
(30, 'Add the Product for Testing', 'add-the-product-for-testing', 18, 2, 3, 'A PVC (Polyvinyl Chloride) pipeline is a system of pipes and fittings made from rigid plastic material, used to convey liquids or gases from one point', 'A PVC (Polyvinyl Chloride) pipeline is a system of pipes and fittings made from rigid plastic material, used to convey liquids or gases from one point', 'products/BjzpjeGfOzthGPJFf8nJLuXXpRN4O8pRJCAQvqvn.jpg', '0.00', NULL, 0, 0, 0, 0, 0, 1, '2026-02-04 06:12:28', '2026-02-16 04:54:21', '2026-02-16 04:54:21'),
