(320, 'MCB Distribution box Flat', 'mcb-distribution-box-flat', 15, 3, 3, 'An MCB Distribution Box is an electrical enclosure used to safely distribute power', 'An MCB Distribution Box is an electrical enclosure used to safely distribute power to multiple circuits in a building. It houses Miniature Circuit Breakers (MCBs) that protect wiring and appliances from overloads and short circuits, ensuring safe and organized electrical control for homes, offices, and commercial spaces.', 'products/QHNnsqB20ZPkpimdXRcF05DChgLsf6OiOPP9SAGv.jpg', '0.00', NULL, 0, 0, 0, 0, 0, 1, '2026-07-03 03:04:18', '2026-07-03 03:04:18', NULL),
(321, 'PVC Chapti', 'pvc-chapti', 12, 3, 3, 'PVC cable trunking (wiring chapti)', 'high-quality bundle of white PVC cable trunking, commonly known as a wiring chapti, designed for surface-mounted electrical wiring installations. Manufactured from durable, high-impact PVC, these cable channels provide a neat, secure, and professional solution for organizing and protecting electrical wires, communication cables, and network cables along walls and ceilings.', 'products/pUKHz2FBiR3LgawldtueVmrkzwdkqvBIZJGKE0nt.png', '0.00', NULL, 0, 0, 0, 0, 0, 1, '2026-07-03 05:25:33', '2026-07-03 05:25:33', NULL);
